#!/usr/bin/env bash
set -euo pipefail
REGION="us-east-1"
WORK="$(mktemp -d)"

# --- baked self-signed certificates (base64 PEM) ---
D1C=''
D1K=''
D2C=''
D2K=''
HC=''
HK=''

echo "$D1C" | base64 -d > "$WORK/d1.crt"; echo "$D1K" | base64 -d > "$WORK/d1.key"
echo "$D2C" | base64 -d > "$WORK/d2.crt"; echo "$D2K" | base64 -d > "$WORK/d2.key"
echo "$HC"  | base64 -d > "$WORK/h.crt";  echo "$HK"  | base64 -d > "$WORK/h.key"

imp() {
  aws acm import-certificate --region "$REGION" \
    --certificate "fileb://$1" --private-key "fileb://$2" \
    --query CertificateArn --output text
}
A1="$(imp "$WORK/d1.crt" "$WORK/d1.key")"   # vera2-checkout  RSA-2048 (visible)
A2="$(imp "$WORK/d2.crt" "$WORK/d2.key")"   # vera2-payments  RSA-2048 (visible)
AH="$(imp "$WORK/h.crt"  "$WORK/h.key")"    # vera2-admin     RSA-4096 (hidden by default list)

python3 - "$REGION" "$A1" "$A2" "$AH" <<'PY'
import json,sys
region,a1,a2,ah=sys.argv[1:5]
state={
 "region":region,
 "certs":[
   {"arn":a1,"domain":"vera2-checkout.internal.example","keyalg":"RSA-2048","hidden":False},
   {"arn":a2,"domain":"vera2-payments.internal.example","keyalg":"RSA-2048","hidden":False},
   {"arn":ah,"domain":"vera2-admin.internal.example","keyalg":"RSA-4096","hidden":True},
 ],
 "all_arns":[a1,a2,ah],
}
json.dump(state,open("seed_state.json","w"),indent=2)
PY
rm -rf "$WORK"
echo "seeded 3 vera2 ACM certs (2x RSA-2048 visible + 1x RSA-4096 hidden-by-default): $A1 $A2 $AH"
